// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(address attacker, uint256 amount) public {
        vm.assume(attacker != address(0));
        vm.assume(attacker != address(c));
        vm.assume(attacker != c.Owner());
        vm.assume(amount > 0);

        vm.deal(address(c), amount);
        vm.prank(attacker);
        try c.withdraw() {
            assertEq(address(c).balance, amount);
        } catch {
            assertEq(address(c).balance, amount);
        }
    }
}
